"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["29806"],{40402(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>f,frontMatter:()=>h,contentTitle:()=>a,toc:()=>l,assets:()=>r});var n=JSON.parse('{"id":"tangfen/newthoughts","title":"","description":"Miss Chan proved that Mathematics\' claim that \\"all human thoughts can be stored in a binary computer\\" is wrong. The definitions and proofs within are easily understood by anyone who has professionally studied mathematics. Since there are too many humanities and engineering students here who haven\'t received professional training and seem to have difficulty understanding, I\'ll take the trouble to help enlighten them on Miss Chan\'s behalf.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/newthoughts.md","sourceDirName":"tangfen","slug":"/tangfen/newthoughts","permalink":"/en/tangfen/newthoughts","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"newthoughts","title":"","hide_table_of_contents":true,"sidebar_label":"Let me explain on Ms. Chan\'s behalf why new thoughts under her definition must be new thoughts!"},"sidebar":"tangfenSidebar","previous":{"title":"A small suggestion: on forums, everyone should consciously follow debate norms","permalink":"/en/tangfen/keepregulations"},"next":{"title":"Let me try once more to explain things clearly to Math on Ms. Chan\'s behalf","permalink":"/en/tangfen/talkforchanagain"}}'),s=o(74848),i=o(28453);let h={id:"newthoughts",title:"",hide_table_of_contents:!0,sidebar_label:"Let me explain on Ms. Chan's behalf why new thoughts under her definition must be new thoughts!"},a="Let Me Explain on Miss Chan's Behalf Why the New Thought She Defined Must Be a New Thought!",r={},l=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"let-me-explain-on-miss-chans-behalf-why-the-new-thought-she-defined-must-be-a-new-thought",children:"Let Me Explain on Miss Chan's Behalf Why the New Thought She Defined Must Be a New Thought!"})}),"\n",(0,s.jsx)(t.p,{children:"Miss Chan proved that Mathematics' claim that \"all human thoughts can be stored in a binary computer\" is wrong. The definitions and proofs within are easily understood by anyone who has professionally studied mathematics. Since there are too many humanities and engineering students here who haven't received professional training and seem to have difficulty understanding, I'll take the trouble to help enlighten them on Miss Chan's behalf."}),"\n",(0,s.jsx)(t.p,{children:'The key difficulty of Miss Chan\'s proof lies in this sentence: "Then we construct a thought as follows: U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A. This thought is obviously not in set A, and it cannot be simplified into any thought in A, because this thought speaks of expression, so any tricks of logical simplification are useless."'}),"\n",(0,s.jsx)(t.p,{children:"Let me explain why the thought Miss Chan constructed must be a new thought. For simplicity, let's use an example where set A contains only four propositions: B, B-, True, False, where B- represents the logical negation of B, B can be any proposition, and True and False represent the logical values 1 and 0. Following Miss Chan's \"we construct a thought as follows: U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A,\" we obtain a new proposition:"}),"\n",(0,s.jsx)(t.p,{children:'"The expression of this thought differs from thought B AND the expression of this thought differs from thought B- AND the expression of this thought differs from thought True AND the expression of this thought differs from thought False"'}),"\n",(0,s.jsx)(t.p,{children:'The proposition in these quotation marks is obviously different from the original four propositions B, B-, True, False. One cannot perform logical operations on the new proposition to produce a logical simplification process like (B+B-+True+False)- = False, because the proposition here is defined in terms of "expression." This is also what Miss Chan means by "this thought is obviously not in set A, and it cannot be simplified into any thought in A, because this thought speaks of expression, so any tricks of logical simplification are useless."'}),"\n",(0,s.jsx)(t.p,{children:'What if the original four propositions were: "the expression of this thought differs from thought a1," "the expression of this thought differs from thought a2," "the expression of this thought differs from thought a3," "the expression of this thought differs from thought a4"? The situation is still unchanged, because the corresponding new proposition would be:'}),"\n",(0,s.jsx)(t.p,{children:"\"The expression of this thought differs from the thought 'the expression of this thought differs from thought a1' AND the expression of this thought differs from the thought 'the expression of this thought differs from thought a2' AND the expression of this thought differs from the thought 'the expression of this thought differs from thought a3' AND the expression of this thought differs from the thought 'the expression of this thought differs from thought a4'\""}),"\n",(0,s.jsx)(t.p,{children:"The proposition in quotation marks is still different from the original four propositions. For any N propositions, the situation is analogous. Whether N is finite, infinite, or even transfinite, the essence of the proof doesn't change, because Miss Chan's entire proof does not depend on whether things are finite or infinite -- because she uses the diagonal method."}),"\n",(0,s.jsx)(t.p,{children:"Some people just don't understand. They think the diagonal method must have an actual diagonal, asking all day: how do you find the diagonal in 00, 11, 01, 10? Or: with finite digits but infinite numbers, how do you find the diagonal? They don't realize that \"diagonal method\" is just a colloquial name and doesn't require actually finding any diagonal. If the thing being proved has nothing to do with numbers, can the diagonal method not be used? That would be the greatest joke ever!"}),"\n",(0,s.jsx)(t.p,{children:'The essence of the diagonal method lies in constructing something new that differs from everything previously posited. Such construction methods can be infinitely many; whether there is an actual diagonal is irrelevant. For example, in Miss Chan\'s construction, one can replace "expression" with "word count of the expression," "color," "phase," "height" -- there are infinite possibilities, as long as the constructed result is guaranteed to differ from all original propositions. The possibilities for such constructions are truly infinite.'}),"\n",(0,s.jsx)(t.p,{children:'The diagonal method is generally used to counter propositions that claim "all" such-and-such. The method is to gather what the opponent claims as "all" into a set, then construct an element that differs from all elements in the set, thereby using proof by contradiction to show that the claimed "all" is wrong. Someone might say: can\'t I just add your constructed element back into the set? Once someone raises this question, it only shows they haven\'t even studied middle school mathematics. It\'s like someone questioning mathematical induction: if assuming the proposition holds for arbitrary N allows us to derive it holds for N+1, and therefore the proposition holds for all natural numbers, then what about N+2? To such people, I can only borrow Miss Chan\'s catchphrase: go back and study!'})]})}function f(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,t,o){o.d(t,{R:()=>h,x:()=>a});var n=o(96540);let s={},i=n.createContext(s);function h(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:h(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);